const fs = require('fs');
const sub = JSON.parse(fs.readFileSync('submission.json','utf8'));
const schemaOk = sub.task_id === 'jacobian/apollonius-gap-repair' &&
  sub.conclusion === 'OMITTED_APOLLONIUS_IDENTITY_REPAIRED' &&
  sub.claimed_assurance === 'COMPUTED' &&
  sub.scope === 'OPC_TEST_ROW_1_ANNOTATED_COORDINATE_GAP' &&
  sub.completeness === 'COMPLETE' &&
  Array.isArray(sub.evidence) && sub.evidence.length === 1 &&
  sub.evidence[0].path === 'evidence/answer.txt' &&
  sub.evidence[0].sha256 === 'sha256:8d12f081c3635b68270b883f50f46b4a215c26b84961226697a695658514ce05' &&
  Array.isArray(sub.limitations) && sub.limitations.length === 1;
const result = sub.result;
const resOk = result.k === '2' && result.c === '3' && result.p === '2' && result.q === '6' && result.center === '4' && result.radius === '2' &&
  JSON.stringify(result.circle_coefficients) === JSON.stringify(['1','1','-8','12']) &&
  JSON.stringify(result.distance_coefficients) === JSON.stringify(['-3','-3','24','-36']) && result.multiplier === '-3';
const ans = fs.readFileSync('evidence/answer.txt','utf8').trimEnd().split('\\n');
const ansOk = ans.length === 4 && ans[0] === 'apollonius-coefficient-certificate-v1' && ans[1] === 'multiplier: -3' && ans[2] === 'circle_coefficients: 1,1,-8,12' && ans[3] === 'distance_coefficients: -3,-3,24,-36';
console.log(JSON.stringify({schemaOk,resOk,ansOk,lines:ans.length}, null, 2));
if ("'!schemaOk || !resOk || !ansOk) process.exit(1);
NODE'

